#include <iostream>
#include <memory>
#include <vector>
#include <optional>
struct Sensor {
    bool conectado=false;
    double umbral=0;
    virtual ~Sensor()=default;
    virtual std::optional<double> medir() const=0;
    bool alarma() const { auto valor=medir(); return conectado && valor && *valor>umbral; }
};
struct Simple : Sensor {
    double valor;
    explicit Simple(double v) : valor(v) {}
    std::optional<double> medir() const override { return conectado ? std::optional<double>(valor) : std::nullopt; }
};
struct Grupo : Sensor {
    std::vector<std::unique_ptr<Sensor>> hijos;
    std::optional<double> medir() const override {
        if(!conectado) return std::nullopt;
        double suma=0; int n=0;
        for(const auto& hijo : hijos) { auto valor=hijo->medir(); if(valor) { suma+=*valor; ++n; } }
        return n ? std::optional<double>(suma/n) : std::nullopt;
    }
};
int main() {
    Grupo grupo; grupo.conectado=true; grupo.umbral=20;
    auto a=std::make_unique<Simple>(10); a->conectado=true;
    auto b=std::make_unique<Simple>(40); b->conectado=true;
    grupo.hijos.push_back(std::move(a)); grupo.hijos.push_back(std::move(b));
    std::cout << *grupo.medir() << ' ' << grupo.alarma() << '\n';
}

